INSERT INTO `Festival`
VALUES ('2025-12-06', 0, '2025-07-05', '2025-09-05 06:34:16', 1, '2025-09-05 06:34:16', '충남 공주시', '제민천 밤페스타',
        '충남 공주시 우체국길 15 (반죽동) 제민천 일대',
        '7월부터 12월까지 매월 첫째 주 토요일마다 켜지는 제민천의 밤에서는 제민천을 따라 펼쳐지는 다양한 부스, 갤러리, 야간 토크쇼로 제민천 일대를 가득 채울 예정이다. 오직 공주시에서만 맛볼 수 있는 다양한 주류와 음식들로 제민천 부스를 가득 채우고, 낭만과 예술의 거리 제민천 갤러리의 밤을 밝히는 것은 물론, 멋진 야외 강연과 감성 무대로 관광객의 눈과 마음을 채울 예정이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=b03bf1da-0c4c-4640-8f8a-cfcf8e0d76f2&cntntsNm=%EC%A0%9C%EB%AF%BC%EC%B2%9C%EB%B0%A4%ED%8E%98%EC%8A%A4%ED%83%80'),
       ('2025-10-31', 0, '2025-06-27', '2025-09-05 06:34:16', 2, '2025-09-05 06:34:16', '경기 가평군', '가평 양떼목장 수국축제',
        '경기 가평군 설악면 유명로 1209 ',
        '가평의 아름다운 자연 속에서 펼쳐지는 본 축제는, 활짝 핀 가을 수국의 물결과 사랑스러운 알파카들을 한자리에서 만날 수 있다. 가을의 정취를 가득 담은 수국밭을 거닐며 싱그러움을 만끽하고, 순수하고 귀여운 알파카들에게 직접 먹이를 주거나 함께 사진을 찍으며 잊지 못할 추억을 만들 수 있다. 단순히 꽃과 동물을 감상하는 것을 넘어, 방문객들이 직접 참여하고 즐길 수 있는 다채로운 프로그램들이 마련되어 있다. 수국밭 속 양떼목장에서는 동물들에게 먹이를 주는 체험을 할 수 있으며, 흥미로운 앵무새 공연도 준비되어 있다. 이와 더불어, 사계절 썰매를 무료로 이용하거나 주말에 진행되는 OX 퀴즈에 참여하며 즐거운 시간을 보낼 수 있다. 뿐만 아니라, 프리마켓 등 다양한 소비자 참여형 이벤트가 축제의 활기를 더하고, 맛있는 빵과 음료를 즐길 수 있는 베이커리 & 카페도 운영되어 풍성한 경험을 제공된다. 자연의 아름다움과 순수한 동물과의 교감이 어우러진 가평 가을 수국 & 알파카 축제에서 특별하고 행복한 시간을 만들 수 있다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=a69de91d-67d2-4b13-b7c2-23eb27115df0&cntntsNm=%EA%B0%80%ED%8F%89%EC%96%91%EB%96%BC%EB%AA%A9%EC%9E%A5%EC%88%98%EA%B5%AD%EC%B6%95%EC%A0%9C'),
       ('2025-12-31', 0, '2024-10-22', '2025-09-05 06:34:16', 3, '2025-09-05 06:34:16', '인천 남동구', '남동 빛의 거리',
        '인천 남동구 만수동  1069, 만수3지구',
        '남동 빛의 거리는 지역별 특색 있는 경관을 조성하여 다양한 볼거리를 제공하며, 뿐만 아니라 버스킹, 지역예술인 문화공연 등 다양한 즐길거리도 제공하고 있다. 빛의 거리는 지역주민과 관광객들에게 힐링과 삶의 여유를 선사하고 있다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=4fd69c49-bcd1-494b-8662-1aad1ef784d3&cntntsNm=%EB%82%A8%EB%8F%99%EB%B9%9B%EC%9D%98%EA%B1%B0%EB%A6%AC'),
       ('2025-10-11', 0, '2025-09-12', '2025-09-05 06:34:16', 4, '2025-09-05 06:34:16', '충북 영동군', '대한민국와인축제',
        '충북 영동군 영동읍 매천리 165 영동와인터널 주차장',
        '국악과 과일의 고장 영동에서 제14회 대한민국와인축제가 2025. 9. 12.(금) ~ 10. 11.(토)까지 30일간 개최된다. 이번 축제의 Healing & Chilling (치유와 여유)로 영동에서 생산된 와인을 자연과 함께 마시며 다채로운 문화 공연을 즐기며 몸과 마음을 회복하는 멀티 테라피형 축제로 진행된다. 장소는 영동세계국악엑스포 초입의 영동와인터널 주차장에서 진행되며 영동군/(재)영동군 문화관광재단, 영동와인연구회가 주최, 주관한다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=4a3c0f8c-0314-4508-80dd-5fedf955c34f&cntntsNm=%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD%EC%99%80%EC%9D%B8%EC%B6%95%EC%A0%9C'),
       ('2025-10-11', 0, '2025-09-12', '2025-09-05 06:34:16', 5, '2025-09-05 06:34:16', '충북 영동군', '영동난계국악축제',
        '충북 영동군 심천면 국악로1길 33',
        '영동군의 문화유산이자 전통문화예술인 국악을 주제로 하여 난계 박연선생의 음악적 업적을 기리고 전통문화예술 진흥에 기여하기 매년 개최되고 있는 문화예술 공연 축제이다. 제55회 영동난계국악축제는 국악이라는 대한민국 유산을 전세계적으로 홍보하여 제2의 한류문화 부흥에 이바지 하고자 한다. 또한 대한민국 유일의 국악축제로 다양한 국악공연과 체험 프로그램을 통한 전통문화예술을 현대적으로 계승하고 지역 특성에 맞는 프로그램으로 축제의 지역관광자원화에 힘쓰고 있다. 지역민의 문화적 수준 향상과 자발적 참여를 통한 군민 화합의 한마당 자리 마련한다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=ba335abd-29f3-4b10-8b7c-29dd2c777fbf&cntntsNm=%EC%98%81%EB%8F%99%EB%82%9C%EA%B3%84%EA%B5%AD%EC%95%85%EC%B6%95%EC%A0%9C'),
       ('2025-11-16', 5000, '2025-09-19', '2025-09-05 06:34:16', 6, '2025-09-05 06:34:16', '전북특별자치도 고창군',
        '고창청농원 핑크뮬리축제', '전북특별자치도 고창군 공음면 청천길 41-27 고창청농원',
        '전북특별자치도 고창군 공음면에 위치한 고창청농원에서 가을을 맞아 핑크뮬리시즌을 개최한다. 마을의 옛 이름인 맑은 개을가 마을이라는 뜻의 \'청천(凊川) 마을\'에서 따온 말인 고창청농원은 2만여평의 넓은 공간에 옛 정취를 그대로 간직한 한옥 술암제, 한 숨을 돌릴 수 있는 대형 카페 , 넘실대는 분홍빛 물결의 핑크뮬리 정원, 보랏빛 향기를 머금은 라벤더 정원(5월-6월경),수국정원 등 계절별 꽃들이 조성되어 있는 관광농원이다. 청농원의 핑크뮬리 정원은 약 5000여평에 걸친 분홍 갈대밭과 가을에 만나볼 수 있는 꽃들로 만개시기엔 넘실대는 핑크빛 물결로 장관을 이룬다. 걷는 동안 지루하지 않게 곳곳에 있는 포토존에서 사진 찍는 재미와 핑크뮬리뿐만 아니라 다양한 꽃들도 같이 구경할 수 있어 가을 감성을 듬뿍 느낄 수 있다. 한옥의 넓은 마당에서 아이들은 반려동물과 함께 뛰어놀고 산책하기 좋은 대나무 숲에서 바람에 이는 나뭇잎 소리를 벗삼아 공기 맑고 깨끗한 자연 속에서 편히 쉬었다 가시는 공간이 되길 소망한다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=9fd7c67a-faef-4495-94f5-24548cf91fc3&cntntsNm=%EA%B3%A0%EC%B0%BD%EC%B2%AD%EB%86%8D%EC%9B%90%ED%95%91%ED%81%AC%EB%AE%AC%EB%A6%AC%EC%B6%95%EC%A0%9C'),
       ('2025-11-04', 10000, '2025-09-19', '2025-09-05 06:34:16', 7, '2025-09-05 06:34:16', '충남 태안군', '태안 가을꽃박람회',
        '충남 태안군 남면 마검포길 200 네이처월드',
        '태안 가을꽃박람회는 코리아플라워파크의 인적자원과 식재 노하우가 접목되어 펼쳐지는 화훼 전시·연출 박람회이다. 올해는 장소를 이전하여 네이처월드에서 펼쳐지게 되며 국화, 산파첸스, 버베나, 클레오메 외에도 가을에 만나볼 수 있는 모든 꽃들이 한 데 어우러져 장관을 이루는 것이 특징이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=e4b65b19-8c0c-4436-9d07-dc6cd41e777a&cntntsNm=%ED%83%9C%EC%95%88%EA%B0%80%EC%9D%84%EA%BD%83%EB%B0%95%EB%9E%8C%ED%9A%8C'),
       ('2025-10-11', 0, '2025-09-20', '2025-09-05 06:34:16', 8, '2025-09-05 06:34:16', '충남 아산시', '아산 전국 프린지 페스티벌',
        '충남 아산시 염치읍 은행나무길 293 아산시 곡교천 은행나무길 일원',
        '올해로 16회 개최에 빛나는 \'아산 전국프린지 페스티벌\'은 전국의 많은 공연팀들이 참여하여 경연을 펼치는 페스티벌이다. 청소년 및 문화 예술 향유자들의 문화 표현 기회 제공과 건전한 문화 형성 기반 조성을 위해 기획되었으며, 전 국민을 대상으로 장르에 구분 없이, 아마추어에서 전문 단체에 이르기까지 누구나 자유롭게 참여할 수 있는 축제이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=76f97b6c-9ecb-4207-a140-e93ae8906cf9&cntntsNm=%EC%95%84%EC%82%B0%EC%A0%84%EA%B5%AD%ED%94%84%EB%A6%AC%EC%A7%80%ED%8E%98%EC%8A%A4%ED%8B%B0%EB%B2%8C'),
       ('2025-10-03', 0, '2025-09-21', '2025-09-05 06:34:16', 9, '2025-09-05 06:34:16', '부산 해운대구', '페스티벌 시월',
        '부산 해운대구 APEC로 55 (우동) 벡스코',
        '17개의 국제행사 동시개최 예정이며 벡스코 빌리지 야외행사장에서 진행되는 테마하우스 국가관(글로벌체험), 테마하우스(체험관), 컨벤션하우스(콘퍼런스 및 포럼 공간), F&B관(글로벌 음식체험), 특설 무대공연, 사일런트 파티(무소음 DJ파티), 클럽디 오아시스 공연 예정이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=ac0047c0-38e3-49e9-813f-3f4af7988d43&cntntsNm=%ED%8E%98%EC%8A%A4%ED%8B%B0%EB%B2%8C%EC%8B%9C%EC%9B%94'),
       ('2025-10-03', 5000, '2025-09-24', '2025-09-05 06:34:16', 10, '2025-09-05 06:34:16', '충북 청주시', '청원생명축제',
        '충북 청주시 청원구 오창읍 미래지로 99 미래지농촌테마공원',
        '청원생명축제는 2008년부터 친환경을 테마로 구성된 대표적인 축제이다. 순수자연으로 더욱 빛나는 명품농산물인 청원생명브랜드를 홍보하고, 테마가 있는 전시와 다양한 체험행사 및 문화공연을 통해 관람객의 다양한 볼거리를 제공하며, 자라나는 학생들에게는 농업의 현재와 미래, 다양한 문화를 느낄 수 있는 교육의 장을 마련하고자 노력하고 있다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=0b996b95-7aa9-4e4e-938b-3bd7cc503f78&cntntsNm=%EC%B2%AD%EC%9B%90%EC%83%9D%EB%AA%85%EC%B6%95%EC%A0%9C'),
       ('2025-10-05', 0, '2025-09-26', '2025-09-05 06:34:16', 11, '2025-09-05 06:34:16', '경북 안동시', '안동국제탈춤페스티벌',
        '경북 안동시 육사로 239 (운흥동)',
        '안동국제탈춤페스티벌은 세계 보편문화인 탈과 탈춤의 보편적인 가치를 전승하고, 그 매력을 함께 향유하고자 하는 \'탈춤\' 의 축제이다. 유네스코 인류무형문화유산으로 등재된 한국의 탈춤은 물론, 25개국 34개 단체의 공연을 집대성해 여러 나라의 탈춤을 모두 경험할 수 있다. 탈춤공연장 공연과 도심 속 거리 퍼레이드, 세계 탈놀이 경연대회 등이 진행되며, 각 나라 별로 탈과 탈춤이 가지고 있는 표정과 이야기를 발견할 수 있는 시간을 선사할 예정이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=644495a7-65e3-42ef-8993-e18e2e71a8bd&cntntsNm=%EC%95%88%EB%8F%99%EA%B5%AD%EC%A0%9C%ED%83%88%EC%B6%8C%ED%8E%98%EC%8A%A4%ED%8B%B0%EB%B2%8C'),
       ('2025-10-05', 0, '2025-09-26', '2025-09-05 06:34:16', 12, '2025-09-05 06:34:16', '전남 영광군', '영광불갑산상사화축제',
        '전남 영광군 불갑면 불갑사로 450 영광군 불갑사관광지 일원',
        '매년 9월 상사화 개화시기에 맞춰, 국내 최대 붉은 꽃무릇 군락지를 이루는 영광군 불갑사관광지에서 개최되는 축제이다. 상사화는 꽃과 잎이 만날 수 없어 그리움, 애틋함, 참사랑을 상징한다. 제25회 영광불갑산상사화축제는 ‘상사화랑 머물GO!, 상사호랑 찍古!’를 주제로 9월26일부터 10월 5일까지 개최된다. 온 산을 붉게 수놓는 상사화와 함께하는 꽃길걷기, 상사화 달빛야행 등의 대표 프로그램과 상사화를 테마로 한 다양한 경연, 공연, 체험, 전시행사가 펼쳐진다. 올해는 온오프라인을 연계한 프로그램 개발, 다회용기 사용을 통한 친환경 축제, 상사화 아카이빙을 통한 추억 되새기기, 영광군 관광지와 연계한 이벤트 강화, 편의시설 확대 등 더욱 새롭게 관광객을 맞이할 계획이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=50f59373-bf29-455b-8c92-50c4e76f58f5&cntntsNm=%EC%98%81%EA%B4%91%EB%B6%88%EA%B0%91%EC%82%B0%EC%83%81%EC%82%AC%ED%99%94%EC%B6%95%EC%A0%9C'),
       ('2025-10-12', 0, '2025-09-27', '2025-09-05 06:34:16', 13, '2025-09-05 06:34:16', '경기 수원시', '수원화성 미디어아트',
        '경기 수원시 팔달구 장안동 334',
        '2025 수원화성 미디어아트는 세계문화유산 수원화성을 배경으로 정조대왕의 꿈과 비전을 현대적 빛의 예술로 풀어낸 야간 미디어아트 축제이다. 2021년 시작 이후 5년간 이어온 여정을 마무리하는 이번 시즌5는 ‘새빛향연(饗宴)’을 주제로, 화서문에서 장안문까지 성곽 전역을 하나의 거대한 미디어 축제의 장으로 구현한다. 화서문·장안문·장안공원 일원에 초대형 미디어파사드, 인터랙티브 작품, 미디어월, 포토존, 지역상권 연계 프로그램이 운영되며, 시민과 관광객이 함께 참여하고 체험하는 축제로 자리매김하고 있다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=856730a3-5355-4937-a2ae-43309d07af31&cntntsNm=%EC%88%98%EC%9B%90%ED%99%94%EC%84%B1%EB%AF%B8%EB%94%94%EC%96%B4%EC%95%84%ED%8A%B8'),
       ('2025-10-04', 0, '2025-09-27', '2025-09-05 06:34:16', 14, '2025-09-05 06:34:16', '경기 수원시', '수원화성문화제',
        '경기 수원시 팔달구 신풍동 363-31 행궁광장',
        '수원화성문화제는 1795년 정조대왕의 8일간의 행행(行幸) 중 수원화성에서의 4일간의 이야기를 담은 축제로, 세계문화유산 수원화성을 배경으로 고품격 문화예술 콘텐츠를 즐길 수 있다. 또한 원행을묘정리의궤(園幸乙卯整理儀軌)를 기반으로 한 국내 최대 왕실 퍼레이드이자 시민참여형 퍼레이드인 정조대왕 능행차는 축제의 단순한 관람자가 아닌 참여자로서 행사를 즐길 수 있다. 글로벌축제로 선정된 수원화성문화제는 글로벌빌리지 등 외국인을 위한 콘텐츠도 제공한다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=95d65f28-6c8f-4226-9697-a5a4e9edc801&cntntsNm=%EC%88%98%EC%9B%90%ED%99%94%EC%84%B1%EB%AC%B8%ED%99%94%EC%A0%9C'),
       ('2025-11-09', 10000, '2025-10-01', '2025-09-05 06:34:16', 15, '2025-09-05 06:34:16', '경남 고성군', '경남고성공룡세계엑스포',
        '경남 고성군 당항만로 1116  당항포관광지',
        '공룡나라 고성에서 <경남고성공룡세계엑스포>가 2025년 10월 1일부터 11월 9일까지 당항포관광지에서 개최된다. 축제기간 동안 휴무 없이 진행된다. \'공룡과 함께 춤을\'이라는 주제로 열리는 이번 공룡엑스포에서는 공룡을 주제로 한 대한민국 최초의 하늘을 나는 대형 익룡, 환경읠 중요성을 강화하는 대형 정크아크 작품 전시, 공룡퍼레이드와 첨단영상과 디지털 기술을 바탕으로 복원된 공룡을 만나볼 수 있는 공룡 5D영상관, 오색 빛깔 미디어아트 존, 다양한 공룡이 살아 숨쉬는 공룡 캐릭터관, 다채로운 공룡 체험 등을 구성하여 다양한 공룡콘텐츠를 선보인다. 14만평의 넓은 행사장에서 온가족이 안전하게 즐길 수 있는 공룡엑스포 행사장에는 공룡외에도 남녀노소 즐길 수 있는 서커스, 마술, 풍선, 저글링 등 다양한 버스킹 공연도 준비되어 있다. 공룡엑스포에서는 새로운 써클영상, 퍼레이드의 변화, 전시관의 다양한 변화가 이뤄질 예정이다.',
        'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=ce010596-12fe-43cb-9386-3f09a4397ef1&cntntsNm=%EA%B2%BD%EB%82%A8%EA%B3%A0%EC%84%B1%EA%B3%B5%EB%A3%A1%EC%84%B8%EA%B3%84%EC%97%91%EC%8A%A4%ED%8F%AC');

