INSERT INTO `Stay` (areaSize, capacity, isActive, isHomestay, createdAt, host, id, updatedAt, hostName, hostPhone, address, deatilAddress, title, description)
VALUES (30,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,1,'2025-09-08 00:37:27',NULL,NULL,'경기 가평군 상면 수목원길','상면 102-3','한울마을 별채 1호','숲길을 따라 들어서면 시원한 바람이 반겨줘요. 테라스에서 산자락을 바라보며 한가로운 오후를 보내기 좋아요. 정원이 아늑해 가벼운 가드닝을 즐기기에도 좋아요.'),(38,9,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,2,'2025-09-08 00:37:27',NULL,NULL,'경기 가평군 상면 수목원길','상면 104-1','한울마을 별채 2호','창을 여는 순간 초록 풍경이 가득 들어와요. 실내 동선이 단정해 머무는 시간이 편안해요. 주말 머무름에도 부담이 적어 휴식과 취미를 함께 누리기 좋아요.'),(32,7,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,3,'2025-09-08 00:37:27',NULL,NULL,'경기 가평군 상면 수목원길','상면 109-7','한울마을 별채 3호','햇살이 깊게 머무는 거실이 매력적이에요. 아침마다 새소리가 들려 하루의 시작이 상쾌해요. 조용하고 단정한 분위기로 장기 거주에도 잘 어울려요.'),(32,7,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,4,'2025-09-08 00:37:27',NULL,NULL,'경남 하동군 악양면 평사리길','악양면 21-3','하람마을 별채 1호','평사리 들판의 고즈넉함이 집안까지 스며들어요. 마루에서 바람을 맞으며 차 한 잔 하기 좋아요. 자연을 가까이 두고 단정한 일상을 이어가기 좋아요.'),(34,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,5,'2025-09-08 00:37:27',NULL,NULL,'경남 하동군 악양면 평사리길','악양면 25-5','하람마을 별채 2호','한적한 동네 결이 편안함을 만들어줘요. 실내는 따뜻한 톤으로 단정하게 꾸며져 있어요. 산책하기 좋은 길이 가까워 일상 회복에 도움이 돼요.'),(30,6,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,6,'2025-09-08 00:37:27',NULL,NULL,'경남 하동군 악양면 평사리길','악양면 27-1','하람마을 별채 3호','햇살 좋은 마루와 소담한 마당이 포인트예요. 바람이 잘 통해 계절의 변화를 온전히 느낄 수 있어요. 머물수록 정이 드는 아늑한 공간이에요.'),(36,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,7,'2025-09-08 00:37:27',NULL,NULL,'전남 강진군 강진읍 탐진로','강진읍 256-2','아라마을 별채 1호','시야가 트여 답답함이 없어요. 내부는 실용적인 배치로 생활이 편안해요. 하부 수납과 야외 활용이 좋아 취미와 휴식을 균형 있게 즐기기 좋아요.'),(38,9,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,8,'2025-09-08 00:37:27',NULL,NULL,'전남 강진군 강진읍 탐진로','강진읍 260-6','아라마을 별채 2호','바람결이 가볍게 스치는 마당이 기분을 맑게 해줘요. 차분한 무드의 실내가 일상에 안정을 더해줘요. 작은 모임을 갖기에도 아늑한 분위기예요.'),(32,7,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,9,'2025-09-08 00:37:27',NULL,NULL,'전남 강진군 강진읍 탐진로','강진읍 263-4','아라마을 별채 3호','오전 햇살이 깊게 들어오는 창이 인상적이에요. 주변이 조용해 집중과 휴식이 모두 잘 돼요. 사계절 풍경을 집 안에서 편안히 누리기 좋아요.'),(30,6,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,10,'2025-09-08 00:37:27',NULL,NULL,'전남 고흥군 도양읍 비봉로','도양읍 77-2','새길마을 별채 1호','전통의 결이 은은하게 녹아 있어요. 기와선이 만들어내는 포근함이 매력적이에요. 조용히 머물며 책을 읽거나 사색하기 좋은 분위기예요.'),(35,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,11,'2025-09-08 00:37:27',NULL,NULL,'전남 고흥군 도양읍 비봉로','도양읍 80-1','새길마을 별채 2호','마당을 중심으로 실내외가 자연스럽게 이어져요. 저녁 노을이 곱게 스며드는 시간이 특히 아름다워요. 관리가 수월해 주말 머무름도 편해요.'),(36,7,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,12,'2025-09-08 00:37:27',NULL,NULL,'전남 고흥군 도양읍 비봉로','도양읍 82-6','새길마을 별채 3호','담백한 한옥 감성과 현대적 편의가 조화를 이루어요. 바람길이 좋아 사계절 내내 쾌적해요. 한적한 일상 속 온화한 무드가 오래 머물어요.'),(38,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,13,'2025-09-08 00:37:27',NULL,NULL,'전남 곡성군 곡성읍 청계로','곡성읍 13-2','살별마을 별채 1호','정겨운 마을 분위기와 감각적인 한옥 디테일이 어울려요. 사계절 농산물 풍경이 근사해요. 소소한 취미와 여유를 담아내기 좋은 집이에요.'),(42,9,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,14,'2025-09-08 00:37:27',NULL,NULL,'전남 곡성군 곡성읍 청계로','곡성읍 15-1','살별마을 별채 2호','창을 열면 마을의 온기가 전해져요. 산책로와 가까워 하루의 피로가 가볍게 풀려요. 전통의 멋을 일상에서 자연스럽게 누릴 수 있어요.'),(36,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,15,'2025-09-08 00:37:27',NULL,NULL,'전남 곡성군 곡성읍 청계로','곡성읍 18-7','살별마을 별채 3호','은은한 목재 향이 편안함을 더해줘요. 실내는 단정하고 생활성이 좋아 오래 머물기 좋아요. 조용한 밤공기가 깊고 안정적이에요.'),(48,9,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,16,'2025-09-08 00:37:27',NULL,NULL,'전북특별자치도 남원시 광한서로','도통동 25-3','버금마을 별채 1호','복층감의 구조가 주는 리듬이 경쾌해요. 밝은 채광과 아늑한 마당이 하루를 부드럽게 시작하게 해줘요. 생활 반경이 편안해 장기 거주에 잘 맞아요.'),(42,10,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,17,'2025-09-08 00:37:27',NULL,NULL,'전북특별자치도 남원시 광한서로','도통동 29-1','버금마을 별채 2호','현관을 지나면 넉넉한 공간감이 반겨줘요. 외부 수납과 야외 활용도가 높아 취미 생활이 즐거워요. 담백한 분위기로 시간의 결이 곱게 쌓여요.'),(35,8,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,18,'2025-09-08 00:37:27',NULL,NULL,'전북특별자치도 남원시 광한서로','도통동 32-6','버금마을 별채 3호','가까운 생활권과 차분한 동네 결이 조화로워요. 가족과 담소를 나누기 좋은 거실이 매력적이에요. 머물수록 편안함이 깊어지는 집이에요.'),(48,10,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,19,'2025-09-08 00:37:27',NULL,NULL,'충북 영동군 영동읍 난계로','영동읍 298-4','미르마을 별채 1호','넉넉한 외부 동선이 주는 자유로움이 좋아요. 실내는 차분한 톤으로 안정감을 줘요. 계절이 바뀔 때마다 다른 풍경을 만나며 일상을 새롭게 채워요.'),(38,9,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,20,'2025-09-08 00:37:27',NULL,NULL,'충북 영동군 영동읍 난계로','영동읍 301-2','미르마을 별채 2호','바람이 잘 통하는 구조로 머무는 시간이 상쾌해요. 소박한 정원이 있어 작은 모임을 갖기 좋아요. 담백한 마감이 오래 보아도 질리지 않아요.'),(52,11,_binary '',_binary '\0','2025-09-08 00:37:27',NULL,21,'2025-09-08 00:37:27',NULL,NULL,'충북 영동군 영동읍 난계로','영동읍 305-8','미르마을 별채 3호','햇살이 깊게 스며드는 창과 마루가 포근해요. 조용한 야간 분위기가 마음을 안정시켜요. 휴식과 취미를 함께 담아내기 좋은 균형 잡힌 집이에요.'),(34,4,_binary '',_binary '','2025-09-08 03:59:32',1,22,'2025-09-08 03:59:32','김봉수','010-2156-1501','경남 남해군 남면로','701-1','가람마을 사랑방 1호','남쪽 햇살이 깊게 들어와요. 앞마당에 바람이 살랑거려 아침마다 상쾌해요. 작은 화분을 놓고 조용히 쉬기 좋아요.'),(36,6,_binary '',_binary '','2025-09-08 03:59:32',1,23,'2025-09-08 03:59:32','박순자','010-2156-1502','경남 남해군 남면로','701-2','가람마을 사랑방 2호','잔잔한 동네 분위기가 마음을 느긋하게 해줘요. 실내 동선이 단정해서 머무는 시간이 편안해요.'),(40,8,_binary '',_binary '','2025-09-08 03:59:32',1,24,'2025-09-08 03:59:32','이말희','010-2156-1503','경남 남해군 남면로','701-3','가람마을 사랑방 3호','창을 열면 푸른 바람이 먼저 인사해요. 저녁이면 고요함이 내려앉아 책 읽기 좋고, 휴식이 깊어져요.'),(28,4,_binary '',_binary '','2025-09-08 03:59:32',1,25,'2025-09-08 03:59:32','최상길','010-2156-1504','경남 남해군 남면로','701-4','가람마을 사랑방 4호','아담한 공간에 포근함이 가득해요. 마루에 앉아 차 한 잔 하기 좋은 리듬으로 하루가 편안해져요.'),(45,10,_binary '',_binary '','2025-09-08 03:59:32',1,26,'2025-09-08 03:59:32','정영자','010-2156-1505','경남 남해군 남면로','701-5','가람마을 사랑방 5호','넉넉한 마당과 깊은 채광이 매력적이에요. 주말마다 느긋하게 쉬기 좋고, 소소한 취미를 즐기기 편해요.'),(30,6,_binary '',_binary '','2025-09-08 03:59:32',2,27,'2025-09-08 03:59:32','한춘복','010-2156-1511','전남 순천시 해룡로','315-1','눈솔마을 사랑방 1호','초록이 가득한 길목에 있어요. 실내는 담백한 톤으로 안정감이 있고, 바람이 잘 통해 하루가 상쾌해요.'),(32,6,_binary '',_binary '','2025-09-08 03:59:32',2,28,'2025-09-08 03:59:32','오복례','010-2156-1512','전남 순천시 해룡로','315-2','눈솔마을 사랑방 2호','작지만 알찬 구성으로 생활이 편해요. 해질녘 붉은 노을이 스며들어 저녁 시간이 특별해져요.'),(38,8,_binary '',_binary '','2025-09-08 03:59:32',2,29,'2025-09-08 03:59:32','류정남','010-2156-1513','전남 순천시 해룡로','315-3','눈솔마을 사랑방 3호','창 너머로 나무들이 가볍게 흔들려요. 조용한 동네 결이 편안함을 더해주고, 머물수록 정이 들어요.'),(41,10,_binary '',_binary '','2025-09-08 03:59:32',2,30,'2025-09-08 03:59:32','문말선','010-2156-1514','전남 순천시 해룡로','315-4','눈솔마을 사랑방 4호','넉넉한 거실과 아늑한 코너가 어울려요. 취미 공간으로 쓰기 좋아 일상이 풍성해져요.'),(35,6,_binary '',_binary '','2025-09-08 03:59:32',2,31,'2025-09-08 03:59:32','신옥단','010-2156-1515','전남 순천시 해룡로','315-5','눈솔마을 사랑방 5호','햇살이 부드럽게 퍼져 포근해요. 한낮엔 마당에 앉아 바람을 느끼며 여유를 즐기기 좋아요.'),(33,6,_binary '',_binary '','2025-09-08 03:59:32',3,32,'2025-09-08 03:59:32','조말복','010-2156-1521','전북특별자치도 전주시 완산로','77-1','나루마을 사랑방 1호','골목의 온기가 좋고, 밤공기가 차분해요. 실내가 단정해 쉬는 동안 마음이 한결 가벼워져요.'),(37,8,_binary '',_binary '','2025-09-08 03:59:32',3,33,'2025-09-08 03:59:32','장영호','010-2156-1522','전북특별자치도 전주시 완산로','77-2','나루마을 사랑방 2호','밝은 채광과 정돈된 구조가 돋보여요. 작은 식물을 두기에도 좋아 삶의 리듬이 편안해져요.'),(29,4,_binary '',_binary '','2025-09-08 03:59:32',3,34,'2025-09-08 03:59:32','남순이','010-2156-1523','전북특별자치도 전주시 완산로','77-3','나루마을 사랑방 3호','아담하지만 포근해요. 창가 자리에 앉아 오후 햇살을 즐기면 시간이 천천히 흘러요.'),(42,10,_binary '',_binary '','2025-09-08 03:59:32',3,35,'2025-09-08 03:59:32','유만수','010-2156-1524','전북특별자치도 전주시 완산로','77-4','나루마을 사랑방 4호','넉넉한 공간감이 주는 여유가 있어요. 담백한 분위기로 오래 머물수록 편안함이 깊어져요.'),(31,6,_binary '',_binary '','2025-09-08 03:59:32',3,36,'2025-09-08 03:59:32','하금자','010-2156-1525','전북특별자치도 전주시 완산로','77-5','나루마을 사랑방 5호','조용한 골목과 어우러져 소란이 없어요. 가벼운 산책 후 집에 돌아오면 휴식이 더 깊어져요.'),(46,12,_binary '',_binary '','2025-09-08 03:59:32',4,37,'2025-09-08 03:59:32','서학섭','010-2156-1531','경북 경주시 황성로','102-1','도담마을 사랑방 1호','생활권 접근이 편해요. 넓은 마루에 앉으면 바람길이 시원하고, 저녁이면 고요가 내려앉아 깊이 쉬기 좋아요.'),(39,8,_binary '',_binary '','2025-09-08 03:59:32',4,38,'2025-09-08 03:59:32','함춘옥','010-2156-1532','경북 경주시 황성로','102-2','도담마을 사랑방 2호','정갈한 내부와 차분한 색감이 안정감을 줘요. 소소한 취미를 즐기며 하루를 느긋하게 보낼 수 있어요.'),(35,6,_binary '',_binary '','2025-09-08 03:59:32',4,39,'2025-09-08 03:59:32','표말자','010-2156-1533','경북 경주시 황성로','102-3','도담마을 사랑방 3호','햇살이 길게 머무는 창가가 매력적이에요. 한적한 저녁 풍경이 마음을 편하게 만들어줘요.'),(44,10,_binary '',_binary '','2025-09-08 03:59:32',4,40,'2025-09-08 03:59:32','이복순','010-2156-1534','경북 경주시 황성로','102-4','도담마을 사랑방 4호','실내외가 자연스럽게 이어져요. 작은 모임을 갖기에도 좋고, 일상의 리듬이 안정적으로 이어져요.'),(32,6,_binary '',_binary '','2025-09-08 03:59:32',4,41,'2025-09-08 03:59:32','노영철','010-2156-1535','경북 경주시 황성로','102-5','도담마을 사랑방 5호','조용한 동네 결이 머무는 시간을 편안하게 해요. 아침 공기가 상쾌해 하루를 기분 좋게 시작해요.'),(30,6,_binary '',_binary '','2025-09-08 03:59:32',5,42,'2025-09-08 03:59:32','위춘자','010-2156-1541','충북 청주시 상당로','11-1','별하마을 사랑방 1호','담백한 내부 구성에 포근한 무드가 더해져요. 창을 열면 산뜻한 바람이 들어와 하루가 가볍게 풀려요.'),(34,6,_binary '',_binary '','2025-09-08 03:59:32',5,43,'2025-09-08 03:59:32','민기환','010-2156-1542','충북 청주시 상당로','11-2','별하마을 사랑방 2호','차분한 색감이 안정감을 주고, 저녁의 조명이 아늑해요. 머물수록 집의 온기가 느껴져요.'),(37,8,_binary '',_binary '','2025-09-08 03:59:32',5,44,'2025-09-08 03:59:32','고오순','010-2156-1543','충북 청주시 상당로','11-3','별하마을 사랑방 3호','넓게 트인 거실이 편안해요. 주말엔 가벼운 휴식을 즐기며 느긋한 시간을 보내기 좋아요.'),(41,10,_binary '',_binary '','2025-09-08 03:59:32',5,45,'2025-09-08 03:59:32','진상도','010-2156-1544','충북 청주시 상당로','11-4','별하마을 사랑방 4호','야외 공간을 알뜰히 활용할 수 있어요. 바람길이 좋아 계절 내내 쾌적함이 이어져요.'),(29,4,_binary '',_binary '','2025-09-08 03:59:32',5,46,'2025-09-08 03:59:32','배말순','010-2156-1545','충북 청주시 상당로','11-5','별하마을 사랑방 5호','아담한 크기지만 포근함이 커요. 조용한 분위기 속에서 쉬었다 가기 좋은 아늑한 공간이에요.');

